import { useState } from 'react'
import manifest from '../data/images.json'
import { BASE } from '../lib/env'

/**
 * Responsive picture. Images live in public/img/<id>-<w>.{avif,webp}; metadata in src/data/images.json
 * (generated by scripts/images.py). Missing id => branded placeholder block (never a broken image).
 * Parent controls size; pass `ratio` (w/h) to reserve space and keep CLS at 0.
 */
type M = { w: number; h: number; ws: number[]; lqip?: string }
const MAN = manifest as Record<string, M>

export const srcset = (id: string, ext: 'avif' | 'webp') => (MAN[id]?.ws ?? []).filter((w) => ext === 'webp' || w <= 1920).map((w) => `${BASE}img/${id}-${w}.${ext} ${w}w`).join(', ')
export function src(id: string, w = 960) {
  const m = MAN[id]
  if (!m) return ''
  const pick = m.ws.find((x) => x >= w) ?? m.ws[m.ws.length - 1]
  return `${BASE}img/${id}-${pick}.webp`
}

type Props = {
  id: string
  alt: string
  sizes?: string
  ratio?: number
  className?: string
  imgClassName?: string
  priority?: boolean
  fit?: 'cover' | 'contain'
}

export default function Img({ id, alt, sizes = '100vw', ratio, className = '', imgClassName = '', priority, fit = 'cover' }: Props) {
  const m = MAN[id]
  const [loaded, setLoaded] = useState(false)
  const box = { aspectRatio: ratio ? String(ratio) : m ? `${m.w} / ${m.h}` : undefined }
  if (!m)
    return (
      <div role="img" aria-label={alt} data-slot={id} data-placeholder="" className={`relative max-w-full overflow-hidden bg-ink ${className}`} style={box}>
        {/* Placeholder: hairline grid + red tick so empty slots read as intentional during build-out */}
        <div aria-hidden className="absolute inset-0 opacity-[0.18]" style={{ backgroundImage: 'linear-gradient(#fff 1px,transparent 1px),linear-gradient(90deg,#fff 1px,transparent 1px)', backgroundSize: '48px 48px' }} />
        <span aria-hidden className="absolute bottom-4 left-4 h-[3px] w-10 bg-red" />
        <span aria-hidden className="absolute right-4 bottom-3 font-mono text-[10px] tracking-widest text-white/40 uppercase">{id}</span>
      </div>
    )
  return (
    <div
      className={`relative max-w-full overflow-hidden bg-line ${className}`}
      style={{ ...box, backgroundImage: m.lqip ? `url(${m.lqip})` : undefined, backgroundSize: 'cover', backgroundPosition: 'center' }}
    >
      <picture>
        <source type="image/avif" srcSet={srcset(id, 'avif')} sizes={sizes} />
        <source type="image/webp" srcSet={srcset(id, 'webp')} sizes={sizes} />
        <img
          src={src(id)}
          alt={alt}
          width={m.w}
          height={m.h}
          loading={priority ? 'eager' : 'lazy'}
          decoding={priority ? 'sync' : 'async'}
          fetchPriority={priority ? 'high' : 'auto'}
          onLoad={() => setLoaded(true)}
          ref={(el) => {
            if (el?.complete && el.naturalWidth && !loaded) setLoaded(true)
          }}
          className={`absolute inset-0 h-full w-full transition-opacity duration-700 ${fit === 'cover' ? 'object-cover' : 'object-contain'} ${loaded ? 'opacity-100' : 'opacity-0'} ${imgClassName}`}
        />
      </picture>
    </div>
  )
}
